package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import com.android.tools.lint.detector.api.SourceCodeScanner
import org.jetbrains.uast.*

class DiffUtilDetector : Detector(), SourceCodeScanner {
    companion object {
        val ISSUE = Issue.create(
            id = "DiffUtilEquals",
            briefDescription = "Suspicious DiffUtil equality check",
            explanation = """
                `areContentsTheSame` is used by `DiffUtil` to produce diffs. Using identity equality (`==` / `===`) or calling `equals` on a type that does not implement structural equality can cause incorrect diff results and visual artifacts.
            """,
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(DiffUtilDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )

        private const val DIFF_UTIL_CALLBACK = "androidx.recyclerview.widget.DiffUtil.Callback"
        private const val METHOD_NAME = "areContentsTheSame"
    }

    override fun getApplicableUElementTypes() = listOf(UMethod::class.java)

    override fun createUElementHandler(context: JavaContext) = object : UElementHandler() {
        override fun visitMethod(node: UMethod) {
            if (node.name != METHOD_NAME) return
            val containingClass = node.containingClass ?: return
            if (!context.evaluator.inheritsFrom(containingClass, DIFF_UTIL_CALLBACK, false)) return

            val body = node.uastBody ?: return
            body.accept(object : AbstractUVisitor() {
                override fun visitBinaryExpression(node: UBinaryExpression): Boolean {
                    if (node.operator == UastBinaryOperator.IDENTITY_EQUALS ||
                        node.operator == UastBinaryOperator.IDENTITY_NOT_EQUALS) {
                        report(context, node)
                    }
                    return super.visitBinaryExpression(node)
                }

                override fun visitCallExpression(node: UCallExpression): Boolean {
                    val methodName = node.methodName
                    if (methodName == "equals" && node.valueArgumentCount == 1) {
                        val receiver = node.receiver
                        val receiverType = receiver?.getExpressionType()
                        if (receiverType != null && !hasStructuralEquals(context, receiverType)) {
                            report(context, node)
                        }
                    }
                    return super.visitCallExpression(node)
                }
            })
        }
    }

    private fun hasStructuralEquals(context: JavaContext, type: PsiType): Boolean {
        val psiClass = context.evaluator.getTypeClass(type) ?: return false
        // Any? equals is identity by default unless overridden.
        // Check if this class or any superclass (except Any/Object) declares equals.
        var cls: PsiClass? = psiClass
        while (cls != null) {
            for (method in cls.methods) {
                if (method.name == "equals" && method.parameterList.parametersCount == 1) {
                    val paramType = method.parameterList.parameters[0]?.type?.canonicalText
                    if (paramType == "java.lang.Object" || paramType == "kotlin.Any" || paramType == "java.lang.Object?") {
                        // If declared directly in a non-Object class, it's an override.
                        val clsName = cls.qualifiedName
                        if (clsName != "java.lang.Object" && clsName != "kotlin.Any") {
                            return true
                        }
                    }
                }
            }
            cls = cls.superClass
        }
        return false
    }

    private fun report(context: JavaContext, node: UElement) {
        context.report(
            ISSUE,
            node,
            context.getLocation(node),
            "Suspicious equality check in `areContentsTheSame`; ensure you are using structural equality."
        )
    }
}

