            if (method.name == METHOD_NAME) {
                val uMethod = method.toUElement(UMethod::class.java)
                uMethod?.uastBody?.accept(EqualityVisitor(context))
            }
        }
    }

    private class EqualityVisitor(private val context: JavaContext) : AbstractUastVisitor() {
        override fun visitBinaryExpression(node: UBinaryExpression): Boolean {
            val operator = node.operator
            if (operator == UastBinaryOperator.EQUALS || operator == UastBinaryOperator.NOT_EQUALS) {
                if (node.sourcePsi?.language == JavaLanguage.INSTANCE) {
                    val left = node.leftOperand.getExpressionType()
                    val right = node.rightOperand.getExpressionType()
                    if (left != null && right != null && left !is PsiPrimitiveType && right !is PsiPrimitiveType) {
                        context.report(ISSUE, node, context.getLocation(node), MESSAGE)
                    }
                }
            } else if (operator == UastBinaryOperator.IDENTITY_EQUALS || operator == UastBinaryOperator.IDENTITY_NOT_EQUALS) {
                context.report(ISSUE, node, context.getLocation(node), MESSAGE)
            }
            return super.visitBinaryExpression(node)
        }

        override fun visitCallExpression(node: UCallExpression): Boolean {
            if (node.methodName == EQUALS && node.valueArgumentCount == 1) {
                val method = node.resolve() ?: return super.visitCallExpression(node)
                val containingClass = method.containingClass?.qualifiedName
                if (containingClass == JAVA_OBJECT || containingClass == KOTLIN_ANY) {
                    val receiverType = node.receiver?.getExpressionType() ?: return super.visitCallExpression(node)
                    if (receiverType !is PsiPrimitiveType && !isEnum(receiverType)) {
                        context.report(ISSUE, node, context.getLocation(node), MESSAGE)
                    }
                }
            }
            return super.visitCallExpression(node)
        }

        private fun isEnum(type: PsiType): Boolean {
            val cls = context.evaluator.getTypeClass(type) ?: return false
            return cls.isEnum
        }
    }
}
